ALTER TABLE public.participant_rewards ADD COLUMN rank_name text NOT NULL DEFAULT 'recruit' CHECK (rank_name IN ('recruit','contender','veteran','elite','master'));
ALTER TABLE public.participant_rewards ADD COLUMN bracket_wins integer NOT NULL DEFAULT 0 CHECK (bracket_wins >= 0);
ALTER TABLE public.participant_rewards ADD COLUMN bracket_stage integer NOT NULL DEFAULT 0 CHECK (bracket_stage >= 0);
UPDATE public.participant_rewards SET rank_name = CASE WHEN points >= 10000 THEN 'master' WHEN points >= 5000 THEN 'elite' WHEN points >= 2000 THEN 'veteran' WHEN points >= 500 THEN 'contender' ELSE 'recruit' END;
COMMENT ON COLUMN public.participant_rewards.rank_key IS 'DEPRECATED: rank_name contains the finalized Recruit to Master progression.';
CREATE OR REPLACE FUNCTION public.sync_engagement_rank() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.rank_name := CASE WHEN NEW.points >= 10000 THEN 'master' WHEN NEW.points >= 5000 THEN 'elite' WHEN NEW.points >= 2000 THEN 'veteran' WHEN NEW.points >= 500 THEN 'contender' ELSE 'recruit' END; RETURN NEW; END $$;
CREATE TRIGGER sync_engagement_rank BEFORE INSERT OR UPDATE ON public.participant_rewards FOR EACH ROW EXECUTE FUNCTION public.sync_engagement_rank();
ALTER TABLE public.profiles ADD COLUMN accent_key text NOT NULL DEFAULT 'crimson' CHECK (accent_key IN ('crimson','gold','cyan','silver'));
ALTER TABLE public.profiles ADD COLUMN font_key text NOT NULL DEFAULT 'body' CHECK (font_key IN ('body','mono','display','scifi'));
GRANT UPDATE(accent_key,font_key) ON public.profiles TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_profile_cosmetic_unlocks() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pts integer; BEGIN SELECT points INTO pts FROM public.participant_rewards WHERE user_id=NEW.id; pts:=COALESCE(pts,0); IF NEW.accent_key <> 'crimson' AND pts<500 THEN RAISE EXCEPTION 'Accent colors unlock at Contender (500 points)'; END IF; IF NEW.font_key <> 'body' AND pts<2000 THEN RAISE EXCEPTION 'Typography unlocks at Veteran (2000 points)'; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.enforce_profile_cosmetic_unlocks() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER enforce_profile_cosmetic_unlocks BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.enforce_profile_cosmetic_unlocks();
CREATE TABLE public.engagement_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, action text NOT NULL CHECK(action IN ('stream_quarter','tournament_entry','prediction','wager','referral')), source_key text NOT NULL, points integer NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,action,source_key));
GRANT SELECT ON public.engagement_events TO authenticated;
GRANT ALL ON public.engagement_events TO service_role;
ALTER TABLE public.engagement_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads reward history" ON public.engagement_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.award_verified_engagement(_user_id uuid,_action text,_source_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE award integer; inserted uuid; BEGIN award:=CASE _action WHEN 'stream_quarter' THEN 10 WHEN 'tournament_entry' THEN 250 WHEN 'prediction' THEN 50 WHEN 'wager' THEN 50 WHEN 'referral' THEN 100 ELSE NULL END; IF award IS NULL OR char_length(_source_key)<1 THEN RAISE EXCEPTION 'Invalid verified engagement'; END IF; INSERT INTO public.engagement_events(user_id,action,source_key,points) VALUES(_user_id,_action,_source_key,award) ON CONFLICT DO NOTHING RETURNING id INTO inserted; IF inserted IS NULL THEN RETURN false; END IF; UPDATE public.participant_rewards SET points=points+award,updated_at=now() WHERE user_id=_user_id; RETURN true; END $$;
REVOKE EXECUTE ON FUNCTION public.award_verified_engagement(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.award_verified_engagement(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.reward_tournament_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.award_verified_engagement(NEW.user_id,'tournament_entry',NEW.id::text); RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.reward_tournament_entry() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER reward_tournament_entry AFTER INSERT ON public.tournament_registrations FOR EACH ROW EXECUTE FUNCTION public.reward_tournament_entry();
CREATE TABLE public.participant_avatars(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,storage_path text NOT NULL,prompt text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.participant_avatars TO authenticated;
GRANT ALL ON public.participant_avatars TO service_role;
ALTER TABLE public.participant_avatars ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own or opted in participant avatar" ON public.participant_avatars FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.leaderboard_visible=true));
CREATE TABLE public.avatar_forge_blocks(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,status_code integer NOT NULL,reason text NOT NULL,blocked_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.avatar_forge_blocks TO service_role;
ALTER TABLE public.avatar_forge_blocks ENABLE ROW LEVEL SECURITY;